const T=['Job Summary','Contract & Changes','Billing & Payments','Job Files','Closeout'];const base=[{id:'jane',demo:1,status:'Active',customer:'Jane Doe',project:'Insurance restoration · Kitchen + water damage',approved:28400,invoiced:28400,paid:24100,docs:['Insurance Estimate.pdf','Signed Contract.pdf','Change Order 1.pdf','Invoice 1048.pdf','Cabinet Sub Invoice.pdf'],items:{contract:'ok',changes:'ok',invoice:'ok',payment:'wait',subs:'ok',insurance:'ok'},issues:['$4,300 customer balance remains','Customer payment confirmation still needed']},{id:'john',demo:1,status:'Attention',customer:'John Smith',project:'Residential remodel · Addition + interior',approved:46200,invoiced:51400,paid:30000,docs:['Signed Contract.pdf','Unsigned Change Order.pdf','Invoice 2117.pdf','Customer Payment.pdf','Electrical Invoice.pdf'],items:{contract:'ok',changes:'problem',invoice:'ok',payment:'ok',subs:'wait',insurance:'ok'},issues:['Change order amount is invoiced but not signed','Electrical invoice has not been marked paid']}];let jobs=structuredClone(base),sel='jane',tab=0,filter='All';const $=x=>document.getElementById(x),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n||0),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cur=()=>jobs.find(j=>j.id===sel);function shown(){let q=$('search').value.toLowerCase();return jobs.filter(j=>(filter==='All'||j.status===filter)&&(!q||(j.customer+' '+j.project).toLowerCase().includes(q)))}function metrics(){let a=jobs.filter(j=>j.status!=='Archived'),ap=a.reduce((s,j)=>s+j.approved,0),iv=a.reduce((s,j)=>s+j.invoiced,0),pd=a.reduce((s,j)=>s+j.paid,0);$('mJobs').textContent=a.length;$('mAttention').textContent=a.filter(j=>j.issues.length).length;$('mApproved').textContent=money(ap);$('mInvoiced').textContent=money(iv);$('mPaid').textContent=money(pd);$('mOut').textContent=money(Math.max(0,iv-pd))}function attention(){let a=jobs.filter(j=>j.status!=='Archived'&&j.issues.length);$('attention').innerHTML=a.length?a.map(j=>'<button data-go="'+j.id+'"><b>'+esc(j.customer)+'</b> — '+esc(j.issues[0])+'</button>').join(''):'<p class="muted">Nothing needs attention right now.</p>';document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{sel=b.dataset.go;tab=0;render()})}function filters(){let f=['All','Active','Attention','Complete','Archived'];$('filters').innerHTML=f.map(x=>'<button class="btn filter '+(filter===x?'active':'')+'" data-filter="'+x+'">'+x+'</button>').join('');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()})}function stage(){let a=shown();$('stage').innerHTML=a.length?a.map(j=>'<button class="jobcard '+(j.id===sel?'active':'')+'" data-job="'+j.id+'"><strong>'+esc(j.customer)+'</strong><span class="muted">'+esc(j.project)+'</span><div class="tag">'+(j.demo?'Demo · ':'')+j.status+'</div><div><b>'+money(Math.max(0,j.invoiced-j.paid))+'</b> outstanding</div><div class="muted">'+(j.issues.length?j.issues.length+' items need attention':'Ready')+'</div></button>').join(''):'<p class="muted">No jobs match this view.</p>';document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{sel=b.dataset.job;tab=0;render()})}const label=v=>v==='ok'?'<span class="ok">Done</span>':v==='wait'?'<span class="wait">Still needed</span>':'<span class="problem">Needs review</span>';function workspace(){let j=cur();if(!j){$('workspace').classList.add('hidden');return}$('workspace').classList.remove('hidden');$('jobHead').innerHTML='<div class="between"><div><div class="muted">'+(j.demo?'DEMO JOB':j.status.toUpperCase())+'</div><h2>'+esc(j.customer)+'</h2><p class="muted">'+esc(j.project)+'</p></div><div class="actions">'+(j.demo?'<button id="resetBtn" class="btn">Reset demo</button>':'<button id="archiveBtn" class="btn">'+(j.status==='Archived'?'Restore job':'Archive job')+'</button><button id="removeBtn" class="btn danger">Remove job</button>')+'</div></div>';$('tabs').innerHTML=T.map((n,i)=>'<button class="tab '+(i===tab?'active':'')+'" data-tab="'+i+'">'+n+'</button>').join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=+b.dataset.tab;workspace()});body(j);if($('removeBtn'))$('removeBtn').onclick=()=>{if(confirm('Remove '+j.customer+'?')){jobs=jobs.filter(x=>x.id!==j.id);sel=jobs[0]?.id||null;render()}};if($('archiveBtn'))$('archiveBtn').onclick=()=>{j.status=j.status==='Archived'?'Active':'Archived';render()};if($('resetBtn'))$('resetBtn').onclick=()=>{jobs[jobs.findIndex(x=>x.id===j.id)]=structuredClone(base.find(x=>x.id===j.id));render()}}function body(j){let out=Math.max(0,j.invoiced-j.paid),h='';if(tab===0)h='<div class="money"><div>Approved<b>'+money(j.approved)+'</b></div><div>Invoiced<b>'+money(j.invoiced)+'</b></div><div>Paid<b>'+money(j.paid)+'</b></div><div>Outstanding<b>'+money(out)+'</b></div></div><h3>What needs attention</h3>'+(j.issues.length?j.issues.map(x=>'<div class="need">'+esc(x)+'</div>').join(''):'<p class="muted">Nothing is currently flagged.</p>');if(tab===1)h='<h3>Contract & Changes</h3><div class="row"><span>Signed contract / approved estimate</span>'+label(j.items.contract)+'</div><div class="row"><span>All change orders signed</span>'+label(j.items.changes)+'</div>';if(tab===2)h='<h3>Billing & Payments</h3><div class="money"><div>Approved<b>'+money(j.approved)+'</b></div><div>Invoiced<b>'+money(j.invoiced)+'</b></div><div>Collected<b>'+money(j.paid)+'</b></div><div>Customer balance<b>'+money(out)+'</b></div></div><div class="row"><span>Customer invoices accounted for</span>'+label(j.items.invoice)+'</div><div class="row"><span>Customer payments documented</span>'+label(j.items.payment)+'</div><div class="row"><span>Subcontractor / supplier bills accounted for</span>'+label(j.items.subs)+'</div>';if(tab===3)h='<h3>Job Files</h3><div class="drop"><input id="upload" type="file" multiple><p class="muted">Add contracts, change orders, invoices, receipts, insurance paperwork, and subcontractor bills.</p></div>'+j.docs.map((d,i)=>'<div class="file"><span>'+esc(d)+'</span><button class="btn danger" data-file="'+i+'">Remove</button></div>').join('');if(tab===4){let c=[['Contract signed',j.items.contract],['All change orders signed',j.items.changes],['Customer fully invoiced',j.items.invoice],['Customer payments documented',j.items.payment],['Subcontractors accounted for',j.items.subs],['Insurance paperwork accounted for',j.items.insurance]];h='<h3>Ready to Close?</h3>'+c.map(x=>'<div class="row"><span>'+x[0]+'</span>'+label(x[1])+'</div>').join('')+'<h3>Still needed</h3>'+(j.issues.length?j.issues.map(x=>'<div class="need">'+esc(x)+'</div>').join(''):'<p class="ok">This job has no open closeout items.</p>')}$('tabBody').innerHTML=h;if(tab===3){$('upload').onchange=e=>{[...e.target.files].forEach(f=>{if(!j.docs.includes(f.name))j.docs.push(f.name)});workspace()};document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{j.docs.splice(+b.dataset.file,1);workspace()})}}function render(){metrics();attention();filters();stage();workspace()}$('newBtn').onclick=()=>$('newPanel').classList.toggle('hidden');$('search').oninput=stage;$('newForm').onsubmit=e=>{e.preventDefault();let id='job-'+Date.now();jobs.push({id,demo:0,status:'Active',customer:$('customer').value.trim(),project:$('project').value.trim(),approved:0,invoiced:0,paid:0,docs:[],items:{contract:'wait',changes:'wait',invoice:'wait',payment:'wait',subs:'wait',insurance:'wait'},issues:['Signed contract or approved estimate needed','Billing and payment information not documented yet']});sel=id;filter='All';e.target.reset();$('newPanel').classList.add('hidden');render()};render();